    "fields": [
      "card",
      "card_io",
      "description",
      "engine",
      "expected",
      "id",
      "inputs",
      "outputs",
      "params",
      "retries",
      "skip_when",
      "timeout_s"
    ],
    "id": "stage id (unique; edges reference it)",
    "engine": "one of engines above (validated at compile)",
    "card": "optional action-card id \u2014 opts the stage into the typed card gate (params validated against the card schema)",
    "params": "the engine's verbatim surface (workflow / out_dir / timeout_s for comfyui; task/family for audio_cpp) \u2014 unvalidated here unless card= is set",
    "inputs": "name -> {\"initial\": key} (a request key) or {\"stage\": id, \"output\": name} (an earlier stage's output; kind is INFERRED upstream)",
    "outputs": "name -> Kind string (omit for the engine default)",
    "expected": "name -> Kind string (what each input expects; required unless card= fills it)",
    "skip_when": "{\"initial\": key, \"when\": \"present|absent\"} \u2014 prunes the stage at build time",
    "edge_rules": "edges must point at EARLIER stages; a kind mismatch refuses at compile with both kinds named"
  },
  "flow_body": {
    "keys": [
      "description",
      "id",
      "stages"
    ],
    "example": {
      "id": "my-flow",
      "stages": [
        {
          "id": "gen",
          "engine": "anycreature",
          "inputs": {
            "prompt": {
              "initial": "prompt"
