    "start": "POST /v1/flows/start with exactly one of {\"flow\": name} | {\"flow_inline\": {...}} | {\"model\": id}, PLUS a REQUIRED doc-backed \"draft_id\" on the envelope (CARD BIRTH LAW: compose at POST /v1/flows/drafts first \u2014 a cardless start 4xxes BEFORE any run registers)",
    "validate": "POST /v1/flows/validate with {\"flow_inline\": {...}} \u2014 verbatim compile refusals, no queue slot, no GPU, no sidecar",
    "status": "GET /v1/flows/status/<run_id> \u2014 stages, progress, queue_position",
    "stop": "POST /v1/flows/stop/<run_id>"
  },
