    "anny-hmr": {
      "description": "Pilot stroke 1 (docs/plans/anny-pilot.md \u00a74): photo \u2192 Anny body GLB via the estimator pack (MultiHMR2 regression + loud single-person lock) \u2014 the first SUB-ACTION verb's flow template; the anny card's HMR chip runs this through the queue and hydrates body_glb from its artifacts.",
      "stages": [
        {
          "id": "estimate",
          "engine": "comfyui",
          "card": "",
          "description": "MultiHMR2 regression + loud single-person lock",
          "inputs": {
            "photo": {
              "initial": "photo"
            }
          },
          "outputs": {
            "body": "mesh"
          },
          "expected": {
            "photo": "image"
