      "stages": [
        {
          "id": "instantiate",
          "engine": "comfyui",
          "card": "",
          "description": "Preset params \u2192 grounded anny GLB",
          "inputs": {
            "params_json": {
              "initial": "params_json"
            }
          },
          "outputs": {
            "body": "mesh"
          },
          "expected": {
            "params_json": "text"
